<?php
/** Write result value object. @package OBEngine\Writing */
namespace OBEngine\Writing;
defined( 'ABSPATH' ) || exit;
final class Write_Result {
	private $status; private $message; private $post_id; private $post_type; private $post_status; private $result_redacted; private $created_at;
	public function __construct( array $data ) { $status = isset( $data['status'] ) ? sanitize_key( (string) $data['status'] ) : Write_Status::FAILED; $this->status = Write_Status::is_valid( $status ) ? $status : Write_Status::FAILED; $this->message = isset( $data['message'] ) ? sanitize_textarea_field( wp_strip_all_tags( (string) $data['message'] ) ) : ''; $this->post_id = isset( $data['post_id'] ) ? absint( $data['post_id'] ) : 0; $this->post_type = isset( $data['post_type'] ) ? sanitize_key( (string) $data['post_type'] ) : ''; $this->post_status = isset( $data['post_status'] ) ? sanitize_key( (string) $data['post_status'] ) : ''; $this->result_redacted = isset( $data['result_redacted'] ) && is_array( $data['result_redacted'] ) ? $this->sanitize_redacted( $data['result_redacted'] ) : array(); $this->created_at = isset( $data['created_at'] ) ? sanitize_text_field( (string) $data['created_at'] ) : ( function_exists( 'current_time' ) ? current_time( 'mysql' ) : gmdate( 'Y-m-d H:i:s' ) ); }
	public static function success( int $post_id, string $post_type, string $post_status, string $message = '' ): self { return new self( array( 'status' => Write_Status::WRITTEN, 'message' => $message ?: __( 'WordPress draft created.', 'ob-engine' ), 'post_id' => $post_id, 'post_type' => $post_type, 'post_status' => $post_status, 'result_redacted' => array( 'post_id' => $post_id, 'post_type' => $post_type, 'post_status' => $post_status ) ) ); }
	public static function failed( string $message, array $context = array() ): self { return new self( array( 'status' => Write_Status::FAILED, 'message' => $message, 'result_redacted' => $context ) ); }
	public function to_array(): array { return array( 'status' => $this->status, 'message' => $this->message, 'post_id' => $this->post_id, 'post_type' => $this->post_type, 'post_status' => $this->post_status, 'result_redacted' => $this->result_redacted, 'created_at' => $this->created_at ); }
	public function is_success(): bool { return Write_Status::WRITTEN === $this->status; } public function is_failed(): bool { return Write_Status::FAILED === $this->status; } public function get_status(): string { return $this->status; } public function get_message(): string { return $this->message; } public function get_post_id(): int { return $this->post_id; } public function get_post_type(): string { return $this->post_type; } public function get_post_status(): string { return $this->post_status; } public function get_result_redacted(): array { return $this->result_redacted; } public function get_created_at(): string { return $this->created_at; }
	private function sanitize_redacted( array $data ): array { $clean = array(); foreach ( $data as $key => $value ) { $clean[ sanitize_key( (string) $key ) ] = is_array( $value ) ? $this->sanitize_redacted( $value ) : sanitize_text_field( (string) $value ); } return $clean; }
}
